import { Link } from "react-router-dom";

export default function PrivacyPolicy() {
  return (
    <div className="max-w-4xl mx-auto px-4 py-10 text-[#2D1E16]">
      <Link to="/" className="text-[#06d2d9] font-semibold">← Back to Home</Link>
      <h1 className="font-display text-3xl font-bold mt-4">Privacy Policy</h1>
      <div className="mt-6 space-y-4 text-sm leading-7 text-[#5C4A3D]">
        <p>SLV Bakery values your privacy and is committed to protecting your personal information.</p>
        <p>We collect your name, phone number, address, and order details only to process and deliver your orders.</p>
        <p>Your information is used solely for order management, delivery communication, and customer support.</p>
        <p>We do not sell or share your personal data with third parties except as required to fulfill your order or comply with legal obligations.</p>
        <p>By using our website, you consent to the collection and use of your information as described here.</p>
      </div>
    </div>
  );
}
